fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : (MockService, CallOutcome) =
  if has_effect(service, key) then
    let call = ServiceCall { key = key, attempt = attempt, kind = ExecuteCall, outcome = Replayed }
    (MockService { ..service, calls = append(service.calls, [call]) }, Replayed)
  elif prior_execute_calls(service, key) < failures then
    let call = ServiceCall { key = key, attempt = attempt, kind = ExecuteCall, outcome = Transient }
    (MockService { ..service, calls = append(service.calls, [call]) }, Transient)
  else
    let call = ServiceCall { key = key, attempt = attempt, kind = ExecuteCall, outcome = Applied }
    (MockService {
      calls = append(service.calls, [call]),
      effects = append(service.effects, [Effect { key = key, amount = amount }])
    }, Applied)

